INSID=S+[['拉丁语：in- + sedēre → insidēre；insidiae','坐在里面、占据；埋伏、圈套'],['拉丁语 insidiōsus → 中古法语 insidieux','暗中设陷阱的、狡猾的'],['英语：insidious','潜伏着造成危害的；阴险的']]
SEDIMENT=S+[['拉丁语：sedimentum','沉下来留下的东西'],['中古法语 sédiment → 英语 sediment','沉积物；沉淀物']]
SUBSID=[PIE,['拉丁语：sīdere（sīdō）','坐下、落定；与 sedēre 同源的动词'],['拉丁语：sub- + sīdere → subsīdere','沉下、平息；停留']]
SUBSIDE=SUBSID+[['英语：subside','下沉、退落；逐渐平息']]
