SEDUL=[['拉丁语：sēdulus','勤勉的；常联系 sēdulō“真诚、认真地”，更早或由“无欺诈”而来'],['英语：sedulous','持续用心的、勤勉的；不能据 sed- 硬接“坐”']]
ASSESS=ASSID+[['拉丁分词 assessus → 中古拉丁语 assessāre','参与审理、估定税额'],['古法语 assesser → 中古英语 assessen','估价、评定'],['英语：assess','评估；估定价值、金额']]
SUBSIDY=SUBSID+[['拉丁语：subsidium','留作后援的兵力；帮助、援助'],['法语 subside / subsidie → 中古英语 subsidie','援助，尤指金钱援助'],['英语：subsidy','补助、补贴']]
SEDARE=[PIE,['拉丁语：sēdāre','使落定、安静；通常视为与 sedēre 相应的使动形式']]
