SEAT=[PIE,['日耳曼语的座位名称；古英语 sǣte、古诺尔斯语 sæti','座位、所在处；两种形式关系及借入影响有不同分析'],['中古英语 sete → 英语 seat','座位；所在地；给……安排座位']]
SETTLE=[PIE,['古英语 setl → setlan','座位 → 安放在固定位置、使坐下'],['中古英语 setlen；与 sahtlen“和解、平息”汇合或受其影响','固定、安定；和解义有另一条历史影响'],['英语：settle','安顿、定居；沉降；解决、结清']]
def D(h,w,m):return h+[['英语：'+w,m]]
